// DeepCopyInto is a deepcopy function, copying the receiver, writing into out. in must be non-nil.
func (in *AnalysisMetric) DeepCopyInto(out *AnalysisMetric) {
	*out = *in
}

// DeepCopy is a deepcopy function, copying the receiver, creating a new AnalysisMetric.
func (in *AnalysisMetric) DeepCopy() *AnalysisMetric {
	if in == nil {
		return nil
	}
	out := new(AnalysisMetric)
	in.DeepCopyInto(out)
	return out
}

