// DeepCopyInto is a deepcopy function, copying the receiver, writing into out. in must be non-nil.
func (in *RolloutStatus) DeepCopyInto(out *RolloutStatus) {
	*out = *in
	if in.StepStartedAt != nil {
		out.StepStartedAt = in.StepStartedAt.DeepCopy()
	}
	if in.LastAnalysisAt != nil {
		out.LastAnalysisAt = in.LastAnalysisAt.DeepCopy()
	}
	if in.Conditions != nil {
		out.Conditions = make([]metav1.Condition, len(in.Conditions))
		for i := range in.Conditions {
			in.Conditions[i].DeepCopyInto(&out.Conditions[i])
		}
	}
	if in.Analysis != nil {
		out.Analysis = make([]MetricAnalysisStatus, len(in.Analysis))
		for i := range in.Analysis {
			in.Analysis[i].DeepCopyInto(&out.Analysis[i])
		}
	}
}

